package fraymus.workspace;

import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;

public class WorkflowTest {
    /** Typed host observations here are unit fixtures. Separate Electron tests execute real pages. */
    static final class Fixture implements AutoCloseable {
        final Path root;final WorkspaceStore artifacts;final SceneStore scenes;final MeasurementStore data;final BrainService brain;final GoalRunner goals;final WorkflowRunner workflows;
        Fixture(Path root) throws Exception {this.root=root;artifacts=new WorkspaceStore(root);scenes=new SceneStore(root);data=new MeasurementStore(root);brain=new BrainService(root);goals=new GoalRunner(root,scenes,brain,artifacts,data);workflows=new WorkflowRunner(root,goals,data,scenes,artifacts);}
        JSONObject source(String csv) throws Exception {return data.importCsv(new JSONObject().put("title","Explicit workflow unit observations").put("filename","observations.csv").put("csv",csv).put("sourceKind","synthetic").put("sourceNote","Unit fixture, not physical observations").put("missingPolicy","reject").put("mapping",new JSONObject().put("timeColumn","t").put("distanceColumn","x").put("timeUnit","s").put("distanceUnit","m")));}
        JSONObject input(JSONObject source){return new JSONObject().put("request","Analyze observations, run a separate native trial and build an evidence explorer").put("title","Workflow test").put("modelName","unit-control").put("datasetId",source.getString("datasetId")).put("datasetVersion",1).put("saveSkillName","unit-evidence");}
        public void close() throws Exception {workflows.close();goals.close();brain.close();scenes.close();artifacts.close();}
    }
    static JSONObject ack(GoalRunner goals,JSONObject e,JSONObject result) throws Exception {return goals.acknowledge(new JSONObject().put("goalId",e.getString("goalId")).put("id",e.getString("id")).put("nonce",e.getString("nonce")).put("result",result));}
    static JSONObject draft(){return new JSONObject().put("files",new JSONObject().put("index.html","<!doctype html><html><body>Explicit lifecycle unit fixture, not browser proof</body></html>")).put("modelName","unit-control").put("modelDigest","a".repeat(64));}
    static void hostFixture(Fixture f,JSONObject e) throws Exception {
        if(e.getString("kind").equals("creation.generate")){ack(f.goals,e,draft());return;}
        var checks=new JSONArray();var steps=e.getJSONArray("steps");for(int i=0;i<steps.length();i++){var s=steps.getJSONObject(i);checks.put(new JSONObject().put("index",i).put("selector",s.getString("selector")).put("passed",true).put("actual",new JSONObject().put("text",s.optString("expectText")).put("value",s.optString("expectValue")).put("count",s.optInt("expectCount",1))));}
        var ref=e.getJSONObject("report");var proof=f.artifacts.recordTest(new JSONObject().put("id",ref.getString("id")).put("version",ref.getInt("version")).put("steps",steps).put("checks",checks));ack(f.goals,e,e.getString("kind").equals("creation.test")?new JSONObject().put("id",ref.getString("id")).put("version",ref.getInt("version")):proof);
    }
    static JSONObject softwareAuditFixture(WorkspaceStore store,JSONObject effect,JSONObject bundle,boolean wrong) throws Exception {
        var raw=MeasurementStore.csv(bundle.getJSONObject("contents").getString("evidence.csv"));var rows=new JSONArray();var a=new JSONArray();var p=new JSONArray();var meta=new JSONObject(bundle.getJSONObject("contents").getString("evidence.json"));double ymax=meta.getDouble("plotYMaxM");
        for(var r:raw.subList(1,raw.size())){rows.put(new JSONArray(r));if(!r.getFirst().equals("observations")){var points=r.getFirst().equals("native_actual")?a:p;points.put(new JSONArray(List.of(40+720*Double.parseDouble(r.get(1))/1.5,260-220*Double.parseDouble(r.get(2))/ymax)));}}
        if(wrong)rows.getJSONArray(0).put(2,"invented value");var plots=new JSONArray();for(var entry:Map.of("native_actual",a,"native_prediction",p).entrySet())plots.put(new JSONObject().put("series",entry.getKey()).put("visible",true).put("viewBox",new JSONArray(List.of(0,0,800,300))).put("points",entry.getValue()));
        return new JSONObject().put("id",effect.getJSONObject("report").getString("id")).put("version",effect.getJSONObject("report").getInt("version")).put("rows",rows).put("plots",plots);
    }
    static JSONObject workflowAck(Fixture f,JSONObject e,JSONObject actual) throws Exception {return f.workflows.acknowledge(new JSONObject().put("workflowId",e.getString("workflowId")).put("id",e.getString("id")).put("nonce",e.getString("nonce")).put("result",actual));}
    static JSONObject driveToAudit(Fixture f,String id) throws Exception {long limit=System.currentTimeMillis()+80_000;while(System.currentTimeMillis()<limit){var w=f.workflows.read(id);if(w.getString("status").equals("interrupted"))throw new AssertionError(w.toString());var audit=f.workflows.claim();if(audit.has("id"))return audit;var e=f.goals.claim();if(e.has("id"))hostFixture(f,e);Thread.sleep(10);}throw new AssertionError("Workflow failed to reach independent audit");}
    static JSONObject completed(Fixture f,String id) throws Exception {for(int i=0;i<1000;i++){var w=f.workflows.read(id);if(!w.getString("status").equals("running"))return w;Thread.sleep(10);}throw new AssertionError("Workflow did not settle");}
    @Test public void sourceAndHandlerContractsRejectInvalidRequestsBeforeAnyGoal() throws Exception {
        try(var f=new Fixture(Files.createTempDirectory("workflow-contract"))){var source=f.source("t,x\n0,0\n0.1,0.01\n0.2,0.03\n");assertThrows(IllegalArgumentException.class,()->f.workflows.start(f.input(source).put("handler","shell")));assertThrows(IllegalArgumentException.class,()->f.workflows.start(f.input(source).put("datasetVersion",1.5)));assertThrows(IllegalArgumentException.class,()->f.workflows.start(f.input(source).put("parameters",new JSONObject().put("friction",.9))));assertEquals(0,f.goals.list().length());assertFalse(f.goals.busy());}
    }
    @Test public void originalNativeStagesAndIndependentFailureDriveBoundedRepairThenWorkflowSkill() throws Exception {
        try(var f=new Fixture(Files.createTempDirectory("workflow-real-native"))){var source=f.source("t,x\n0,0\n0.1,0.01\n0.2,0.03\n");var w=f.workflows.start(f.input(source));String id=w.getString("id");assertThrows(IllegalStateException.class,()->f.goals.start(new JSONObject()));var e=driveToAudit(f,id);w=f.workflows.read(id);String nativeRun=w.getJSONArray("stages").getJSONObject(1).getString("runId"),artifact=e.getJSONObject("report").getString("id");var bundle=f.artifacts.read(w.getJSONObject("bundle").getString("id"));assertEquals(source.getString("csv"),bundle.getJSONObject("contents").getString("original-observations.csv"));
            var wrong=softwareAuditFixture(f.artifacts,e,bundle,true);workflowAck(f,e,wrong);assertEquals(0,f.goals.procedures().length());var repaired=driveToAudit(f,id);assertEquals(artifact,repaired.getJSONObject("report").getString("id"));assertEquals(2,repaired.getJSONObject("report").getInt("version"));workflowAck(f,repaired,softwareAuditFixture(f.artifacts,repaired,bundle,false));w=completed(f,id);assertEquals("completed",w.getString("status"));assertEquals(nativeRun,w.getJSONArray("stages").getJSONObject(1).getString("runId"));assertEquals(2,w.getJSONArray("auditHistory").length());assertFalse(w.getJSONArray("auditHistory").getJSONObject(0).getBoolean("passed"));assertEquals(61,w.getJSONObject("metrics").getInt("evidenceRows"));assertEquals(1,f.goals.procedures().length());assertEquals(WorkflowRunner.PROCEDURE,f.goals.procedures().getJSONObject(0).getString("kind"));assertFalse(f.goals.workflowReserved());
            var other=f.source("t,x\n0,0\n0.1,0.02\n0.2,0.05\n0.3,0.07\n");var reuse=f.workflows.reuse(new JSONObject().put("name","unit-evidence").put("version",1).put("datasetId",other.getString("datasetId")).put("datasetVersion",1).put("parameters",new JSONObject().put("angleDeg",30).put("friction",.1)));assertNotEquals(id,reuse.getString("id"));assertEquals(other.getString("datasetId"),reuse.getJSONObject("dataBinding").getString("datasetId"));f.workflows.cancel(reuse.getString("id"));
        }
    }
    @Test public void restartAfterCompletedPhysicsReusesNativeRunAndPassingIndependentAudit() throws Exception {
        Path root=Files.createTempDirectory("workflow-restart");String id,run,artifact;JSONObject effect;
        try(var f=new Fixture(root)){id=f.workflows.start(f.input(f.source("t,x\n0,0\n0.1,0.01\n0.2,0.03\n"))).getString("id");effect=driveToAudit(f,id);var w=f.workflows.read(id);run=w.getJSONArray("stages").getJSONObject(1).getString("runId");artifact=effect.getJSONObject("report").getString("id");synchronized(f.workflows){workflowAck(f,effect,softwareAuditFixture(f.artifacts,effect,f.artifacts.read(w.getJSONObject("bundle").getString("id")),false));f.workflows.close();}}
        try(var f=new Fixture(root)){assertEquals("interrupted",f.workflows.read(id).getString("status"));assertTrue(f.goals.workflowReserved());f.workflows.resume(id);var w=completed(f,id);assertEquals("completed",w.getString("status"));assertEquals(1,w.getInt("resumes"));assertEquals(run,w.getJSONArray("stages").getJSONObject(1).getString("runId"));assertEquals(artifact,w.getJSONObject("report").getString("id"));assertEquals(1,f.artifacts.read(artifact).getInt("version"));assertEquals(1,f.goals.procedures().length());}
    }
    @Test public void detachedControlCancellationAndForeignAuditCannotPromote() throws Exception {
        try(var f=new Fixture(Files.createTempDirectory("workflow-ownership"))){String id=f.workflows.start(f.input(f.source("t,x\n0,0\n0.1,0.01\n0.2,0.03\n"))).getString("id");JSONObject generation=null;for(int i=0;i<8000;i++){var e=f.goals.claim();if(e.has("id")){if(e.getString("kind").equals("creation.generate")){generation=e;break;}hostFixture(f,e);}Thread.sleep(10);}assertNotNull(generation);final var g=generation;assertThrows(IllegalStateException.class,()->f.goals.cancel(g.getString("goalId")));assertThrows(IllegalStateException.class,()->f.goals.saveProcedure(g.getString("goalId"),"detached"));assertThrows(IllegalStateException.class,()->f.workflows.acknowledge(new JSONObject().put("workflowId",id).put("id",UUID.randomUUID()).put("nonce",UUID.randomUUID()).put("result",new JSONObject().put("passed",true))));f.workflows.cancel(id);assertEquals("cancelled",f.workflows.read(id).getString("status"));assertThrows(IllegalStateException.class,()->ack(f.goals,g,draft()));assertFalse(f.goals.workflowReserved());assertEquals(0,f.goals.procedures().length());}
    }
    @Test public void bundleEditsArePreservedAndNeverSilentlyRebound() throws Exception {
        try(var f=new Fixture(Files.createTempDirectory("workflow-source-edit"))){String id=f.workflows.start(f.input(f.source("t,x\n0,0\n0.1,0.01\n0.2,0.03\n"))).getString("id");var e=driveToAudit(f,id);var w=f.workflows.read(id);var b=f.artifacts.read(w.getJSONObject("bundle").getString("id"));f.artifacts.write(new JSONObject().put("id",b.getString("id")).put("expectedVersion",1).put("title","User edit retained").put("files",new JSONObject().put("evidence.csv","series,time_s,position_m,source_kind\nchanged,0,99,synthetic\nchanged,1,99,synthetic\n")));workflowAck(f,e,softwareAuditFixture(f.artifacts,e,b,false));assertEquals("interrupted",f.workflows.read(id).getString("status"));assertEquals("User edit retained",f.artifacts.read(b.getString("id")).getString("title"));assertEquals(0,f.goals.procedures().length());}
    }
    @Test public void geometryAndEveryCellAreVerifiedAgainstFrozenCoordinatesNotPassedFlags() throws Exception {
        try(var store=new WorkspaceStore(Files.createTempDirectory("workflow-geometry"))){var a=store.write(new JSONObject().put("title","Geometry software control").put("files",new JSONObject().put("index.html","<html><body>Explicit unit control</body></html>")));var b=new JSONObject().put("contents",new JSONObject().put("evidence.csv","series,time_s,position_m,source_kind\nobservations,0,0,synthetic\nnative_actual,0.5,1.0,native simulation\nnative_prediction,0.5,0.9,native model forecast\n").put("evidence.json","{\"plotYMaxM\":2.0}"));var e=new JSONObject().put("report",Creation.reference(a));var result=softwareAuditFixture(store,e,b,false);assertTrue(WorkflowEvidence.audit(a,b,result).getBoolean("passed"));var point=result.getJSONArray("plots").getJSONObject(0).getJSONArray("points").getJSONArray(0);point.put(0,point.getDouble(0)+.03);assertFalse(WorkflowEvidence.audit(a,b,result).getBoolean("passed"));result=softwareAuditFixture(store,e,b,true);assertFalse(WorkflowEvidence.audit(a,b,result).getBoolean("passed"));result.put("passed",true);final var forged=result;assertThrows(IllegalArgumentException.class,()->WorkflowEvidence.audit(a,b,forged));}
    }
    @Test public void stableChildIntentReconcilesAndStopFindsAnUncheckpointedChildPointer() throws Exception {
        try(var f=new Fixture(Files.createTempDirectory("workflow-child-intent"))){var source=f.source("t,x\n0,0\n0.1,0.01\n0.2,0.03\n");synchronized(f.workflows){var w=f.workflows.start(f.input(source));String id=w.getString("id");var input=new JSONObject().put("request",w.getString("request")).put("datasetId",source.getString("datasetId")).put("datasetVersion",1).put("maxGapS",.25).put("speedLimitMps",5);var child=f.goals.startOwned(id,"data",input);assertEquals(child.getString("id"),f.goals.startOwned(id,"data",input).getString("id"));assertThrows(IllegalStateException.class,()->f.goals.startOwned(id,"data",new JSONObject(input.toString()).put("maxGapS",.5)));f.workflows.cancel(id);assertEquals("cancelled",f.goals.read(child.getString("id")).getString("status"));assertFalse(f.goals.busy());}}
    }
}
